import { useEffect, useState } from "react";
import { processMarkdown } from "../markdown/processor";

export function MarkdownViewer(props: { content: string; relativePath: string }) {
  const [html, setHtml] = useState("");
  const [token, setToken] = useState(0);

  useEffect(() => {
    let alive = true;
    const my = token + 1;
    setToken(my);
    const t = window.setTimeout(() => {
      void processMarkdown(props.content).then((r) => {
        if (alive && my >= token) setHtml(r.html);
      });
    }, 120);
    return () => {
      alive = false;
      window.clearTimeout(t);
    };
  }, [props.content]);

  return (
    <section className="preview" aria-label="Preview">
      <div className="preview-body" dangerouslySetInnerHTML={{ __html: html }} />
    </section>
  );
}
